const input = $input.first().json ?? {};

const headers = input.headers ?? {};
const body = input.body ?? input;

function getHeader(name) {
  const lower = name.toLowerCase();

  for (const [key, value] of Object.entries(headers)) {
    if (key.toLowerCase() === lower) {
      return Array.isArray(value) ? value[0] : value;
    }
  }

  return null;
}

const topic =
  getHeader('x-shopify-topic') ??
  getHeader('X-Shopify-Topic') ??
  null;

const shopDomain =
  getHeader('x-shopify-shop-domain') ??
  getHeader('X-Shopify-Shop-Domain') ??
  null;

const webhookId =
  getHeader('x-shopify-webhook-id') ??
  getHeader('X-Shopify-Webhook-Id') ??
  null;

const hmac =
  getHeader('x-shopify-hmac-sha256') ??
  getHeader('X-Shopify-Hmac-Sha256') ??
  null;

return [
  {
    json: {
      raw_webhook: {
        headers,
        body,
        topic,
        shop_domain: shopDomain,
        webhook_id: webhookId,
        hmac,
        received_at: new Date().toISOString()
      }
    }
  }
];

const crypto = require('crypto');

const payload = $input.first().json;

const webhook = payload.raw_webhook ?? {};
const receivedHmac = webhook.hmac ?? null;

const secret =
  $vars.SHOPIFY_WEBHOOK_SECRET ?? null;

/*
 * En producción, raw_body debe venir del Webhook/proxy.
 * Si no existe, este fallback reconstruye JSON y sirve solo para DEV.
 */
const rawBody =
  webhook.raw_body ??
  JSON.stringify(webhook.body ?? {});

function safeCompareBase64(a, b) {
  if (!a || !b) {
    return false;
  }

  const aBuffer = Buffer.from(a, 'base64');
  const bBuffer = Buffer.from(b, 'base64');

  if (aBuffer.length !== bBuffer.length) {
    return false;
  }

  return crypto.timingSafeEqual(aBuffer, bBuffer);
}

let valid = false;
let reason = null;

if (!secret) {
  valid = false;
  reason = 'missing_shopify_webhook_secret';
} else if (!receivedHmac) {
  valid = false;
  reason = 'missing_shopify_hmac_header';
} else {
  const calculatedHmac = crypto
    .createHmac('sha256', secret)
    .update(rawBody, 'utf8')
    .digest('base64');

  valid = safeCompareBase64(
    calculatedHmac,
    receivedHmac
  );

  if (!valid) {
    reason = 'invalid_hmac';
  }
}

return [
  {
    json: {
      ...payload,

      security_validation: {
        valid,
        reason,
        validated_at: new Date().toISOString()
      }
    }
  }
];

const payload = $input.first().json;

const webhook = payload.raw_webhook ?? {};
const order = webhook.body ?? {};

function text(value) {
  if (typeof value !== 'string') {
    return value ?? null;
  }

  const trimmed = value.trim();
  return trimmed.length > 0 ? trimmed : null;
}

function money(value) {
  const number = Number(value);
  return Number.isFinite(number) ? number : null;
}

const topic =
  text(webhook.topic) ??
  'orders/paid';

const financialStatus =
  text(order.financial_status) ??
  text(order.displayFinancialStatus) ??
  null;

let normalizedStatus = 'unknown';

if (
  topic === 'orders/paid' ||
  financialStatus === 'paid' ||
  financialStatus === 'authorized' ||
  financialStatus === 'partially_paid'
) {
  normalizedStatus = 'confirmed';
}

if (
  financialStatus === 'voided' ||
  financialStatus === 'refunded' ||
  financialStatus === 'partially_refunded'
) {
  normalizedStatus = 'failed';
}

const noteAttributes =
  Array.isArray(order.note_attributes)
    ? order.note_attributes
    : [];

const attributes =
  Array.isArray(order.attributes)
    ? order.attributes
    : [];

function findAttribute(key) {
  const allAttributes = [
    ...noteAttributes,
    ...attributes
  ];

  const found = allAttributes.find((item) => {
    const itemKey =
      item.name ??
      item.key ??
      null;

    return itemKey === key;
  });

  return found?.value ?? null;
}

const transactionId =
  text(findAttribute('dalia_transaction_id')) ??
  text(order.dalia_transaction_id) ??
  null;

const businessId =
  text(findAttribute('dalia_business_id')) ??
  text(order.dalia_business_id) ??
  null;

const traceId =
  text(findAttribute('dalia_trace_id')) ??
  text(order.dalia_trace_id) ??
  null;

const requestId =
  text(findAttribute('dalia_request_id')) ??
  text(order.dalia_request_id) ??
  null;

const shopifyOrderId =
  text(order.admin_graphql_api_id) ??
  text(order.id) ??
  null;

const shopifyCartToken =
  text(order.cart_token) ??
  text(order.cartToken) ??
  null;

const shopifyCheckoutId =
  text(order.checkout_id) ??
  text(order.checkout_token) ??
  null;

const eventId =
  text(webhook.webhook_id) ??
  text(order.id) ??
  `${topic}:${shopifyOrderId}:${Date.now()}`;

return [
  {
    json: {
      ...payload,

      normalized_shopify_event: {
        provider: 'shopify',
        topic,
        event_id: eventId,
        shop_domain:
          webhook.shop_domain ?? null,

        normalized_status: normalizedStatus,
        financial_status: financialStatus,

        shopify_order_id: shopifyOrderId,
        shopify_cart_id: shopifyCartToken,
        shopify_checkout_id: shopifyCheckoutId,

        transaction_id: transactionId,
        business_id: businessId,
        trace_id: traceId,
        request_id: requestId,

        total_price:
          money(order.total_price) ??
          money(order.current_total_price),

        currency:
          text(order.currency)?.toUpperCase() ??
          null,

        customer: {
          email:
            text(order.email) ??
            text(order.contact_email) ??
            null,

          phone:
            text(order.phone) ??
            text(order.customer?.phone) ??
            null,

          name:
            text(order.customer?.first_name) && text(order.customer?.last_name)
              ? `${text(order.customer.first_name)} ${text(order.customer.last_name)}`
              : null
        },

        raw: order,

        normalized_at:
          new Date().toISOString()
      }
    }
  }
];

const result = $input.first().json;

const payload =
  result.workflow_payload ?? {};

const event =
  payload.normalized_shopify_event ?? {};

const transaction =
  result.transaction ?? {};

const traceId =
  event.trace_id ??
  `trace_shopify_${event.event_id}`;

const requestId =
  event.request_id ??
  `req_shopify_${event.event_id}`;

return [
  {
    json: {
      request: {
        request_id: requestId,
        action: 'process_payment_event',
        requested_at: new Date().toISOString(),
        source_module: 'DALIA_M5_EVT_Shopify_Payment',
        trace_id: traceId
      },

      context: {
        business_id:
          transaction.business_id ??
          event.business_id ??
          null,

        session_id:
          transaction.metadata?.session_id ??
          null,

        conversation_id:
          transaction.metadata?.conversation_id ??
          null,

        channel: 'shopify_webhook',
        locale: 'es-CO',
        timezone: 'America/Bogota'
      },

      customer: {
        customer_id:
          transaction.customer_id ?? null,

        name:
          event.customer?.name ?? null,

        phone:
          event.customer?.phone ?? null,

        email:
          event.customer?.email ?? null,

        metadata: {
          source: 'shopify_webhook'
        }
      },

      commercial_selection: {
        currency:
          transaction.currency ??
          event.currency ??
          'COP',

        items: [],

        total:
          event.total_price ??
          transaction.total ??
          null,

        customer_confirmation: {
          confirmed: true,
          confirmed_at:
            new Date().toISOString()
        }
      },

      advisor_validation: {
        customer_checked: true,
        product_validated: true,
        price_validated: true,
        stock_checked: true,
        validated_at:
          new Date().toISOString(),
        valid_until:
          new Date(Date.now() + 5 * 60000).toISOString(),
        sources: {
          payment: 'shopify_webhook'
        }
      },

      business_configuration: {
        payment: {
          required: true,
          mode: 'online',
          provider: 'shopify',
          allowed_methods: [
            'shopify_checkout'
          ],
          confirmation_mode: 'callback'
        },

        invoicing:
          transaction.metadata
            ?.business_configuration
            ?.invoicing ?? {
            required: false,
            mode: 'not_applicable'
          },

        fulfillment:
          transaction.metadata
            ?.business_configuration
            ?.fulfillment ?? {
            mode: 'store_pickup',
            requires_address: false,
            requires_city: false,
            requires_email: false,
            requires_phone: false
          },

        completion:
          transaction.metadata
            ?.business_configuration
            ?.completion ?? {
            completion_state: 'picked_up'
          },

        automation:
          transaction.metadata
            ?.business_configuration
            ?.automation ?? {
            level: 'semi_automated',
            allow_human_handoff: true,
            max_retries: 3
          }
      },

      transaction_context: {
        transaction_id:
          transaction.id,

        status:
          transaction.status,

        sub_status:
          transaction.sub_status,

        next_action:
          transaction.next_action
      },

      external_event: {
        provider: 'shopify',
        topic: event.topic,
        event_id: event.event_id,
        shop_domain: event.shop_domain,

        shopify_order_id:
          event.shopify_order_id,

        shopify_cart_id:
          event.shopify_cart_id,

        shopify_checkout_id:
          event.shopify_checkout_id,

        financial_status:
          event.financial_status,

        status:
          event.normalized_status,

        payment_status:
          event.normalized_status,

        total_price:
          event.total_price,

        currency:
          event.currency,

        transaction_id:
          transaction.id,

        raw:
          event.raw
      }
    }
  }
];
